use crate::aap::caps::state_read;

struct Node;

/// Keys tried, in order, in the 'subscriptions' store.
const KEYS: &[&str] = &["urls", "subscriptions"];

impl Guest for Node {
    fn run(_info: RunInfo) -> SubscriptionList {
        let mut urls: Vec<String> = Vec::new();
        for key in KEYS {
            if let Some(raw) = state_read::get(key) {
                let parsed = parse_list(&raw);
                if !parsed.is_empty() {
                    urls = parsed;
                    break;
                }
            }
        }
        SubscriptionList { urls: dedupe(urls) }
    }
}

/// Accept either a JSON array of strings, or newline / comma separated text
/// (blank lines and `#` comments ignored).
fn parse_list(raw: &str) -> Vec<String> {
    let trimmed = raw.trim();
    if trimmed.starts_with('[') {
        if let Some(v) = parse_json_string_array(trimmed) {
            return v
                .into_iter()
                .map(|s| s.trim().to_string())
                .filter(|s| !s.is_empty())
                .collect();
        }
    }
    trimmed
        .split(|c| c == '\n' || c == ',')
        .map(|l| l.trim())
        .filter(|l| !l.is_empty() && !l.starts_with('#'))
        .map(|l| l.to_string())
        .collect()
}

fn dedupe(urls: Vec<String>) -> Vec<String> {
    let mut out: Vec<String> = Vec::with_capacity(urls.len());
    for u in urls {
        if !out.iter().any(|x| x == &u) {
            out.push(u);
        }
    }
    out
}

/// Minimal parser for a JSON array whose elements are strings.
fn parse_json_string_array(s: &str) -> Option<Vec<String>> {
    let chars: Vec<char> = s.chars().collect();
    let mut i = 0usize;
    skip_ws(&chars, &mut i);
    if chars.get(i) != Some(&'[') {
        return None;
    }
    i += 1;
    let mut out = Vec::new();
    skip_ws(&chars, &mut i);
    if chars.get(i) == Some(&']') {
        i += 1;
        skip_ws(&chars, &mut i);
        return if i == chars.len() { Some(out) } else { None };
    }
    loop {
        skip_ws(&chars, &mut i);
        out.push(parse_json_string(&chars, &mut i)?);
        skip_ws(&chars, &mut i);
        match chars.get(i) {
            Some(',') => i += 1,
            Some(']') => {
                i += 1;
                break;
            }
            _ => return None,
        }
    }
    skip_ws(&chars, &mut i);
    if i == chars.len() {
        Some(out)
    } else {
        None
    }
}

fn skip_ws(c: &[char], i: &mut usize) {
    while let Some(ch) = c.get(*i) {
        if ch.is_whitespace() {
            *i += 1;
        } else {
            break;
        }
    }
}

fn hex4(c: &[char], i: &mut usize) -> Option<u32> {
    let mut v = 0u32;
    for _ in 0..4 {
        let d = c.get(*i)?.to_digit(16)?;
        v = v * 16 + d;
        *i += 1;
    }
    Some(v)
}

fn parse_json_string(c: &[char], i: &mut usize) -> Option<String> {
    if c.get(*i) != Some(&'"') {
        return None;
    }
    *i += 1;
    let mut s = String::new();
    loop {
        let ch = *c.get(*i)?;
        *i += 1;
        match ch {
            '"' => return Some(s),
            '\\' => {
                let e = *c.get(*i)?;
                *i += 1;
                match e {
                    '"' => s.push('"'),
                    '\\' => s.push('\\'),
                    '/' => s.push('/'),
                    'b' => s.push('\u{0008}'),
                    'f' => s.push('\u{000C}'),
                    'n' => s.push('\n'),
                    'r' => s.push('\r'),
                    't' => s.push('\t'),
                    'u' => {
                        let hi = hex4(c, i)?;
                        let code = if (0xD800..0xDC00).contains(&hi) {
                            if c.get(*i) == Some(&'\\') && c.get(*i + 1) == Some(&'u') {
                                *i += 2;
                                let lo = hex4(c, i)?;
                                if !(0xDC00..0xE000).contains(&lo) {
                                    return None;
                                }
                                0x10000 + ((hi - 0xD800) << 10) + (lo - 0xDC00)
                            } else {
                                return None;
                            }
                        } else {
                            hi
                        };
                        s.push(char::from_u32(code)?);
                    }
                    _ => return None,
                }
            }
            _ => s.push(ch),
        }
    }
}

export!(Node);
